// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract Voting {
    struct Candidate {
        uint256 id;
        string name;
        uint256 voteCount;
    }

    struct Voter {
        bool isRegistered;
        bool hasVoted;
        uint256 votedCandidateId;
    }

    address public owner;
    address public verifier; // address of the AI backend verifier
    
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    
    event VoterRegistered(address voter);
    event VoteCast(address voter, uint256 candidateId);
    event CandidateAdded(uint256 candidateId, string name);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this");
        _;
    }

    modifier onlyVerifier() {
        require(msg.sender == verifier || msg.sender == owner, "Only verifier can call this");
        _;
    }

    constructor() {
        owner = msg.sender;
        verifier = msg.sender; // Default to owner, can be changed
    }

    function setVerifier(address _verifier) external onlyOwner {
        verifier = _verifier;
    }

    function addCandidate(string memory _name) external onlyOwner {
        candidates.push(Candidate({
            id: candidates.length,
            name: _name,
            voteCount: 0
        }));
        emit CandidateAdded(candidates.length - 1, _name);
    }

    function registerVoter(address _voter) external onlyVerifier {
        require(!voters[_voter].isRegistered, "Voter already registered");
        voters[_voter].isRegistered = true;
        emit VoterRegistered(_voter);
    }

    function vote(uint256 _candidateId) external {
        require(voters[msg.sender].isRegistered, "Voter not registered");
        require(!voters[msg.sender].hasVoted, "Voter already voted");
        require(_candidateId < candidates.length, "Invalid candidate ID");

        voters[msg.sender].hasVoted = true;
        voters[msg.sender].votedCandidateId = _candidateId;
        candidates[_candidateId].voteCount++;

        emit VoteCast(msg.sender, _candidateId);
    }

    function getCandidates() external view returns (Candidate[] memory) {
        return candidates;
    }

    function getCandidateCount() external view returns (uint256) {
        return candidates.length;
    }
}

